def generate_bachata_set(limit=100):
    S = {0}
    queue = [0]
    elements_in_order = []

    while queue:
        n = queue.pop(0)
        if n not in elements_in_order:
             elements_in_order.append(n)

        next_11 = n + 11
        if next_11 <= limit and next_11 not in S:
            S.add(next_11)
            queue.append(next_11)

        next_20 = n + 20
        if next_20 <= limit and next_20 not in S:
            S.add(next_20)
            queue.append(next_20)

    # Return the sorted list of elements up to the limit
    return sorted([e for e in S if e <= limit])

small_set = generate_bachata_set(100)
print(small_set)
